  function fitCanvas(){const v=document.getElementById("canvasViewport");if(!v)return;ui.zoom=Math.max(.2,Math.min((v.clientWidth-42)/WORLD.width,(v.clientHeight-42)/WORLD.height));ui.pan.x=(v.clientWidth-WORLD.width*ui.zoom)/2;ui.pan.y=(v.clientHeight-WORLD.height*ui.zoom)/2;applyCanvasTransform()}
  function zoomAt(delta,cx,cy){const v=document.getElementById("canvasViewport"),r=v.getBoundingClientRect(),old=ui.zoom,next=Math.max(.2,Math.min(2.5,old+delta)),wx=(cx-r.left-ui.pan.x)/old,wy=(cy-r.top-ui.pan.y)/old;ui.zoom=next;ui.pan.x=cx-r.left-wx*next;ui.pan.y=cy-r.top-wy*next;applyCanvasTransform()}
  function startPan(e,v){const sx=e.clientX,sy=e.clientY,px=ui.pan.x,py=ui.pan.y;v.classList.add("panning");const move=ev=>{ui.pan.x=px+ev.clientX-sx;ui.pan.y=py+ev.clientY-sy;applyCanvasTransform()},up=()=>{v.classList.remove("panning");document.removeEventListener("pointermove",move);document.removeEventListener("pointerup",up)};document.addEventListener("pointermove",move);document.addEventListener("pointerup",up)}
  function findObject(event,id,kind){return kind==="table"?event.tables.find(x=>x.id===id):event.venueObjects.find(x=>x.id===id)}
  function startObjectDrag(e,id,kind,el){if(ui.tool!=="select")return;e.preventDefault();e.stopPropagation();const event=activeEvent(),obj=findObject(event,id,kind);ui.selectedObjectId=id;document.querySelectorAll(".selected").forEach(x=>x.classList.remove("selected"));el.classList.add("selected");if(obj.locked){toast("This object is locked. Unlock it in the Inspector.");return render()}const snap=canvasSnapshot(event),sx=e.clientX,sy=e.clientY,ox=obj.x,oy=obj.y;let moved=false;const move=ev=>{let nx=ox+(ev.clientX-sx)/ui.zoom,ny=oy+(ev.clientY-sy)/ui.zoom;if(ui.snap){nx=Math.round(nx/10)*10;ny=Math.round(ny/10)*10}obj.x=Math.max(-obj.w+20,Math.min(WORLD.width-20,nx));obj.y=Math.max(-obj.h+20,Math.min(WORLD.height-20,ny));el.style.left=obj.x+"px";el.style.top=obj.y+"px";moved=true},up=()=>{document.removeEventListener("pointermove",move);document.removeEventListener("pointerup",up);if(moved){recordUndo(event,snap);touchEvent(event)}render()};document.addEventListener("pointermove",move);document.addEventListener("pointerup",up)}
  function startResize(e,id,kind,el){e.preventDefault();e.stopPropagation();const event=activeEvent(),obj=findObject(event,id,kind);if(obj.locked)return toast("Unlock this object before resizing.");const snap=canvasSnapshot(event),sx=e.clientX,sy=e.clientY,ow=obj.w,oh=obj.h,move=ev=>{obj.w=Math.max(kind==="table"?64:30,ow+(ev.clientX-sx)/ui.zoom);obj.h=Math.max(kind==="table"?54:30,oh+(ev.clientY-sy)/ui.zoom);el.style.width=obj.w+"px";el.style.height=obj.h+"px"},up=()=>{document.removeEventListener("pointermove",move);document.removeEventListener("pointerup",up);recordUndo(event,snap);touchEvent(event);render()};document.addEventListener("pointermove",move);document.addEventListener("pointerup",up)}
  function startRotate(e,id,kind,el){e.preventDefault();e.stopPropagation();const event=activeEvent(),obj=findObject(event,id,kind);if(obj.locked)return toast("Unlock this object before rotating.");const snap=canvasSnapshot(event),v=document.getElementById("canvasViewport"),r=v.getBoundingClientRect(),move=ev=>{const cx=r.left+ui.pan.x+(obj.x+obj.w/2)*ui.zoom,cy=r.top+ui.pan.y+(obj.y+obj.h/2)*ui.zoom;let deg=Math.atan2(ev.clientY-cy,ev.clientX-cx)*180/Math.PI+90;if(ui.snap)deg=Math.round(deg/15)*15;obj.rotation=deg;el.style.transform=`rotate(${deg}deg)`},up=()=>{document.removeEventListener("pointermove",move);document.removeEventListener("pointerup",up);recordUndo(event,snap);touchEvent(event);render()};document.addEventListener("pointermove",move);document.addEventListener("pointerup",up)}
  function nextTableNumber(event,bistro){const prefix=bistro?"B":"T",nums=event.tables.filter(t=>t.number.startsWith(prefix)).map(t=>parseInt(t.number.slice(prefix.length),10)||0);return prefix+String(Math.max(0,...nums)+1).padStart(2,"0")}
  function repackTableAssignments(event,table,newCap){const guests=event.guests.filter(g=>g.assignment?.tableId===table.id).sort((a,b)=>Math.min(...a.assignment.seats)-Math.min(...b.assignment.seats)),occupied=guests.reduce((n,g)=>n+paxOf(g),0);if(occupied>newCap)return false;let cursor=0;guests.forEach(g=>{g.assignment.seats=Array.from({length:paxOf(g)},(_,i)=>cursor+i);cursor+=paxOf(g)});return true}
  function setTableCapacity(event,table,newCap){newCap=Math.max(1,Math.min(99,Number(newCap)||1));const occupied=tableAssignedPax(event,table.id);if(newCap<occupied){toast(`${table.number} currently has ${occupied} occupied seats. Capacity cannot be reduced below ${occupied}.`,"error",5000);return false}recordUndo(event);repackTableAssignments(event,table,newCap);table.capacity=newCap;touchEvent(event);render();return true}
  function bindInspector(event){app.querySelectorAll("[data-inspector]").forEach(el=>el.onchange=()=>updateInspectorField(event,el.dataset.inspector,el.value));app.querySelectorAll("[data-inspector-action]").forEach(b=>b.onclick=()=>inspectorAction(event,b.dataset.inspectorAction));app.querySelectorAll("[data-seat-step]").forEach(b=>b.onclick=()=>{const t=event.tables.find(x=>x.id===ui.selectedObjectId);if(t)setTableCapacity(event,t,t.capacity+Number(b.dataset.seatStep))});app.querySelectorAll("[data-seat-capacity]").forEach(b=>b.onclick=()=>{const t=event.tables.find(x=>x.id===ui.selectedObjectId);if(t)setTableCapacity(event,t,Number(b.dataset.seatCapacity))});const custom=app.querySelector("[data-seat-custom]");if(custom)custom.onclick=()=>{const t=event.tables.find(x=>x.id===ui.selectedObjectId),value=prompt("Enter custom seat count",t.capacity);if(value!==null)setTableCapacity(event,t,value)}}
  function updateInspectorField(event,field,value){const t=event.tables.find(x=>x.id===ui.selectedObjectId),o=event.venueObjects.find(x=>x.id===ui.selectedObjectId),obj=t||o;if(!obj)return;if(t&&field==="number"){value=String(value).trim().toUpperCase();if(!value)return render();if(event.tables.some(x=>x.id!==t.id&&x.number===value)){toast("That table number is already in use.","error");return render()}}recordUndo(event);if(["rotation","w","h"].includes(field))value=Number(value);obj[field]=value;if(t&&field==="type"){if(value==="round")t.w=t.h=120;else if(value==="square")t.w=t.h=105;else if(value==="bistro"){t.w=82;t.h=72;t.zone="BISTRO"}else{t.w=170;t.h=86}}touchEvent(event);render()}
  function inspectorAction(event,action){const t=event.tables.find(x=>x.id===ui.selectedObjectId),o=event.venueObjects.find(x=>x.id===ui.selectedObjectId),obj=t||o;if(!obj)return;if(action==="lock"){recordUndo(event);obj.locked=!obj.locked;touchEvent(event);return render()}if(action==="delete")return deleteSelectedObject(event);if(action==="duplicate"){recordUndo(event);const c=clone(obj);c.id=uid(t?"table":"venue");c.x+=20;c.y+=20;c.locked=false;if(t){c.number=nextTableNumber(event,t.type==="bistro");event.tables.push(c)}else event.venueObjects.push(c);ui.selectedObjectId=c.id;touchEvent(event);return render()}if(action==="forward"||action==="backward"){recordUndo(event);obj.z=Math.max(1,(obj.z||10)+(action==="forward"?1:-1));touchEvent(event);render()}}
  function deleteSelectedObject(event){const t=event.tables.find(x=>x.id===ui.selectedObjectId),o=event.venueObjects.find(x=>x.id===ui.selectedObjectId);if(!t&&!o)return;const assigned=t?event.guests.filter(g=>g.assignment?.tableId===t.id):[];if(assigned.length&&!confirm(`${t.number} has ${tableAssignedPax(event,t.id)} assigned guests. Delete it and return them to Unassigned?`))return;if(!assigned.length&&!confirm(`Delete ${t?t.number:o.label}?`))return;recordUndo(event);assigned.forEach(g=>g.assignment=null);if(t)event.tables=event.tables.filter(x=>x.id!==t.id);else event.venueObjects=event.venueObjects.filter(x=>x.id!==o.id);ui.selectedObjectId=null;touchEvent(event);render()}
  function bindBackground(event){const opacity=document.getElementById("bgOpacity");if(opacity){opacity.oninput=()=>{event.background.opacity=Number(opacity.value);const l=document.querySelector(".reference-layer");if(l)l.style.opacity=opacity.value};opacity.onchange=()=>touchEvent(event)}const scale=document.getElementById("bgScale");if(scale){scale.oninput=()=>{event.background.scale=Number(scale.value);const l=document.querySelector(".reference-layer");if(l)l.style.backgroundSize=scale.value+"% auto"};scale.onchange=()=>touchEvent(event)}app.querySelectorAll("[data-bg-action]").forEach(b=>b.onclick=()=>{const a=b.dataset.bgAction;if(a==="import")return document.getElementById("floorPlanFile").click();if(a==="fit")return fitCanvas();recordUndo(event);if(a==="visible")event.background.visible=!event.background.visible;if(a==="lock")event.background.locked=!event.background.locked;if(a==="remove")event.background={src:"",name:"",opacity:.25,visible:false,locked:true,isDefault:false,scale:100};touchEvent(event);render()})}
